function unitMount(w){const sets={length:{m:1,km:1000,cm:.01,mm:.001,mi:1609.344,ft:.3048,in:.0254},mass:{kg:1,g:.001,mg:.000001,lb:.45359237,oz:.0283495},data:{B:1,KB:1024,MB:1048576,GB:1073741824},temperature:{C:1,F:1,K:1}};function update(){const kind=$('.x-kind',w).value,from=$('.x-from',w),to=$('.x-to',w),v=Number($('.x-val',w).value),units=Object.keys(sets[kind]);if(!units.includes(from.value))from.innerHTML=units.map(x=>'<option>'+x+'</option>').join('');if(!units.includes(to.value))to.innerHTML=units.map(x=>'<option>'+x+'</option>').join('');let n=v;if(kind==='temperature'){const c=from.value==='F'?(v-32)*5/9:from.value==='K'?v-273.15:v;n=to.value==='F'?c*9/5+32:to.value==='K'?c+273.15:c;}else n=v*sets[kind][from.value]/sets[kind][to.value];$('.x-result',w).textContent='Result: '+(Number.isFinite(n)?Number(n.toPrecision(8)):'—')+' '+to.value;}w.addEventListener('input',e=>{if(e.target.matches('.x-kind,.x-from,.x-to,.x-val'))update()});w.addEventListener('change',e=>{if(e.target.matches('.x-kind,.x-from,.x-to'))update()});update();}
